input.sparql:
PREFIX brick: <brick:https://brick.schema.org/>
SELECT ?point ?tsid ?uri WHERE {
 ?point rdfs:label "SupplyFan_AHU01" .
 ?point ref:hasTimeseriesId ?tsid .
 ?point ref:hasExternalReference ?uri .
}

SELECT ?point ?label ?tsid WHERE {
 ?point ?p ?o .
 FILTER(str(?point) LIKE "%SupplyFan_AHU01%" || str(?point) LIKE "%Supply%Fan%")
 OPTIONAL { ?point rdfs:label ?label }
 OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}

SELECT ?point ?label ?tsid WHERE {
 ?point ?p ?o .
 FILTER(regex(str(?point), "Supply.*Fan|Supply_Fan", "i") || regex(str(?label), "SupplyFan", "i"))
 OPTIONAL { ?point rdfs:label ?label }
 OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}

SELECT ?point ?tsid WHERE {
 ?point a <http://brickschema.org/schema/1.2/brick#ElectricPowerSensor> .
 FILTER(str(?point) LIKE "%SupplyFan_AHU01%")
 ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?point ?tsid ?ext WHERE {
 ?point ref:hasTimeseriesId ?tsid .
 FILTER(str(?point) LIKE "%SupplyFan_AHU01%")
 OPTIONAL { ?point ref:hasExternalReference ?ext }
}
